// Styling for the interactive floor plans section.
//
// Three columns on desktop — selector, details, plan — following the
// reference's structure while replacing its developer language entirely.
//
// The active option carries a gold ground and a notch pointing at the content,
// which is the one reference detail genuinely worth keeping: it makes the link
// between what you clicked and what changed impossible to miss.
//
// Everything visible is derived from one selected plan. The swap animation is
// driven by a key change on the content, so the details, stats, plan and CTA
// can never disagree about which unit is showing.

import template1 from "./template-1";

export type FloorPlanLabels = {
  bedrooms: string;
  bedroom: string;
  bathrooms: string;
  bathroom: string;
  area: string;
  availabilityLabel: string;
  rentLabel: string;
  rentPeriod: string;
  contactForPricing: string;
  expand: string;
  close: string;
  selectorLabel: string;
};

export type FloorPlanTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
  labels: FloorPlanLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: FloorPlanLabels = {
  bedrooms: "Bedrooms",
  bedroom: "Bedroom",
  bathrooms: "Bathrooms",
  bathroom: "Bathroom",
  area: "Square Feet",
  availabilityLabel: "Availability",
  rentLabel: "Starting From",
  rentPeriod: "/ month",
  contactForPricing: "Contact for pricing",
  expand: "View Floor Plan",
  close: "Close floor plan viewer",
  selectorLabel: "Floor plan",
};

const css = `
.kr-fp {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-fp__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-fp__heading { margin-bottom: ${spacing.headingGap}px; }

/* When a unit has no drawing the viewer column is not rendered, so the two
   remaining columns take the width rather than leaving a gap where the frame
   would have been. */
.kr-fp__layout:not(:has(.kr-fp__viewer)) {
  grid-template-columns: ${layout.selectorColumn} minmax(0, 1fr);
}

.kr-fp__layout {
  display: grid;
  grid-template-columns: ${layout.selectorColumn} ${layout.detailColumn} ${layout.viewerColumn};
  align-items: start;
  gap: ${spacing.columnGap}px;
}

/* ── selector ─────────────────────────────────────────── */
.kr-fp__options {
  display: flex;
  flex-direction: column;
  gap: ${spacing.optionGap}px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.kr-fp__option {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: ${spacing.optionPaddingY}px ${spacing.optionPaddingX}px;
  border: 1px solid ${color.optionBorder};
  border-radius: ${layout.radius}px;
  background: ${color.optionBackground};
  color: ${color.optionText};
  font-family: ${typography.optionFamily};
  font-size: ${typography.optionSize}px;
  font-weight: ${typography.optionWeight};
  letter-spacing: ${typography.optionTracking};
  text-transform: uppercase;
  text-align: left;
  cursor: pointer;
  transition:
    background-color ${timing.hover}ms ${ease},
    border-color ${timing.hover}ms ${ease},
    color ${timing.hover}ms ${ease},
    padding-left ${timing.hover}ms ${ease};
}
/* Gold rule sliding in from the left on hover. */
.kr-fp__option::before {
  content: "";
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  width: 2px;
  background: ${color.optionHoverRule};
  transform: scaleY(0);
  transform-origin: center;
  transition: transform ${timing.hover}ms ${ease};
}
.kr-fp__option:hover:not([aria-selected="true"]) {
  background: ${color.optionHoverBackground};
  padding-left: ${spacing.optionPaddingX + 4}px;
}
.kr-fp__option:hover:not([aria-selected="true"])::before { transform: scaleY(1); }
.kr-fp__option:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 2px; }

.kr-fp__option-number {
  color: ${color.optionNumber};
  font-size: ${typography.optionNumberSize}px;
  transition: color ${timing.hover}ms ${ease};
}

.kr-fp__option[aria-selected="true"] {
  background: ${color.optionActiveBackground};
  border-color: ${color.optionActiveBackground};
  color: ${color.optionActiveText};
}
.kr-fp__option[aria-selected="true"] .kr-fp__option-number {
  color: ${color.optionActiveNumber};
}
.kr-fp__option[aria-selected="true"]::before { transform: scaleY(0); }
/* Notch pointing at the content it controls. */
.kr-fp__option[aria-selected="true"]::after {
  content: "";
  position: absolute;
  left: 100%;
  top: 50%;
  width: 0;
  height: 0;
  border: ${layout.optionNotch}px solid transparent;
  border-left-color: ${color.optionActiveBackground};
  transform: translateY(-50%);
}

/* ── details ──────────────────────────────────────────── */
.kr-fp__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
}
.kr-fp__description {
  margin: 0 0 ${spacing.descriptionGap}px;
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize}px;
  font-weight: ${typography.descriptionWeight};
  line-height: ${typography.descriptionLeading};
}

/* Swap animation: the content block is keyed on the plan, so React remounts
   it and this runs from the start on every change. */
@keyframes kr-fp-swap {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: none; }
}
.kr-fp__detail {
  animation: kr-fp-swap ${timing.swap}ms ${ease} both;
}

.kr-fp__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: ${spacing.statGapY}px 20px;
  margin: 0 0 ${spacing.statsGap}px;
  padding: ${spacing.statsGap}px 0 0;
  border-top: 1px solid ${color.divider};
  list-style: none;
}
.kr-fp__stat { display: flex; flex-direction: column; gap: 8px; }
.kr-fp__stat-icon { color: ${color.statIcon}; display: inline-flex; }
.kr-fp__stat-value {
  color: ${color.statValue};
  font-family: ${typography.statValueFamily};
  font-size: ${typography.statValueSize}px;
  font-weight: ${typography.statValueWeight};
  letter-spacing: -0.02em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.kr-fp__stat-label {
  color: ${color.statLabel};
  font-family: ${typography.statLabelFamily};
  font-size: ${typography.statLabelSize}px;
  font-weight: ${typography.statLabelWeight};
  letter-spacing: ${typography.statLabelTracking};
  text-transform: uppercase;
}

/* Availability never relies on colour alone — the word is always present. */
.kr-fp__availability {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: ${color.availabilityText};
}
.kr-fp__availability--muted { color: ${color.availabilityMuted}; }
.kr-fp__availability-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: ${color.availabilityDot};
  flex-shrink: 0;
}
.kr-fp__availability--muted .kr-fp__availability-dot { background: ${color.availabilityMuted}; }

.kr-fp__rent {
  margin: 0 0 ${spacing.rentGap}px;
  padding-top: ${spacing.rentGap}px;
  border-top: 1px solid ${color.divider};
}
.kr-fp__rent-label {
  display: block;
  margin-bottom: 8px;
  color: ${color.rentLabel};
  font-family: ${typography.rentLabelFamily};
  font-size: ${typography.rentLabelSize}px;
  font-weight: ${typography.rentLabelWeight};
  letter-spacing: ${typography.rentLabelTracking};
  text-transform: uppercase;
}
.kr-fp__rent-value {
  display: flex;
  align-items: baseline;
  gap: 8px;
  color: ${color.rentValue};
  font-family: ${typography.rentValueFamily};
  font-size: ${typography.rentValueSize};
  font-weight: ${typography.rentValueWeight};
  letter-spacing: -0.02em;
  line-height: 1;
}
.kr-fp__rent-period {
  color: ${color.rentPeriod};
  font-family: ${typography.rentLabelFamily};
  font-size: ${typography.rentPeriodSize}px;
  font-weight: 500;
}

.kr-fp__actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: ${spacing.ctaGap}px; }

/* ── plan viewer ──────────────────────────────────────── */
.kr-fp__viewer { position: relative; isolation: isolate; }
.kr-fp__block {
  position: absolute;
  right: -18px;
  bottom: -18px;
  z-index: 0;
  width: ${layout.blockWidth};
  height: ${layout.blockHeight};
  background: ${color.block};
  pointer-events: none;
}
.kr-fp__frame {
  position: relative;
  z-index: 1;
  aspect-ratio: ${layout.viewerAspect};
  padding: ${layout.viewerPad}px;
  background: ${color.viewerBackground};
  border-radius: ${layout.radius}px;
  overflow: hidden;
}
/* Faint drafting grid — architectural without becoming a blueprint. */
.kr-fp__frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(90deg, ${color.viewerGrid} 0 1px, transparent 1px 40px),
    repeating-linear-gradient(0deg, ${color.viewerGrid} 0 1px, transparent 1px 40px);
  pointer-events: none;
}
/* contain, never cover — a cropped floor plan is a useless floor plan. */
.kr-fp__plan {
  position: relative;
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  animation: kr-fp-plan ${timing.plan}ms ${ease} both;
}
@keyframes kr-fp-plan {
  from { opacity: 0; transform: scale(.985); }
  to   { opacity: 1; transform: none; }
}

/* Gold layer sweeping across on change — the same visual language as the
   property hero's reveal. */
.kr-fp__wipe {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: ${color.wipe};
  transform-origin: left center;
  animation: kr-fp-wipe ${timing.wipe}ms ${ease} both;
  pointer-events: none;
}
@keyframes kr-fp-wipe {
  0%   { transform: scaleX(0); transform-origin: left center; }
  45%  { transform: scaleX(1); transform-origin: left center; }
  55%  { transform: scaleX(1); transform-origin: right center; }
  100% { transform: scaleX(0); transform-origin: right center; }
}

.kr-fp__expand {
  position: absolute;
  right: 16px;
  bottom: 16px;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border: 1px solid ${color.expandBorder};
  border-radius: ${layout.radius}px;
  background: ${color.expandBackground};
  color: ${color.expandText};
  font-family: ${typography.expandFamily};
  font-size: ${typography.expandSize}px;
  font-weight: ${typography.expandWeight};
  letter-spacing: ${typography.expandTracking};
  text-transform: uppercase;
  cursor: pointer;
  transition:
    background-color ${timing.hover}ms ${ease},
    border-color ${timing.hover}ms ${ease},
    color ${timing.hover}ms ${ease};
}
.kr-fp__expand:hover {
  background: ${color.expandHoverBackground};
  border-color: ${color.expandHoverBackground};
  color: ${color.expandHoverText};
}
.kr-fp__expand:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── empty state ──────────────────────────────────────── */
.kr-fp__empty {
  padding: 34px 0 0;
  border-top: 1px solid ${color.divider};
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize}px;
  line-height: ${typography.descriptionLeading};
}

/* ── responsive ───────────────────────────────────────────
   Tablet: the selector becomes a scrollable tab row above the content, rather
   than a squeezed third column. */
@media (max-width: ${layout.tabletBelow}px) {
  .kr-fp__layout {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
  }
  .kr-fp__selector { grid-column: 1 / -1; }
  .kr-fp__options {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 4px;
    scrollbar-width: thin;
  }
  .kr-fp__option { white-space: nowrap; }
  .kr-fp__option[aria-selected="true"]::after { display: none; }
}

@media (max-width: ${layout.mobileBelow}px) {
  .kr-fp {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-fp__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-fp__layout { grid-template-columns: minmax(0, 1fr); }
  /* The plan comes before the stats — people want to see the layout first. */
  .kr-fp__viewer { order: 2; }
  .kr-fp__detail-col { order: 3; }
  .kr-fp__block { display: none; }
  .kr-fp__frame { padding: 18px; aspect-ratio: 4 / 3; }
  .kr-fp__stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .kr-fp__detail,
  .kr-fp__plan { animation: none; }
  .kr-fp__wipe { display: none; }
  .kr-fp__option,
  .kr-fp__option::before,
  .kr-fp__expand { transition: none; }
}
`;

/** Without JavaScript the first plan is the one that renders. */
const noscriptCss = `
.kr-fp__detail, .kr-fp__plan { animation: none; opacity: 1; transform: none; }
.kr-fp__wipe { display: none; }
`;

const template: FloorPlanTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-fp",
  timing,
  labels,
};

export default template;
