import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { LuArrowLeft, LuArrowRight, LuExpand } from "react-icons/lu";
import { A11y, Autoplay, Keyboard, Navigation } from "swiper/modules";
import { Swiper, SwiperSlide } from "swiper/react";
import type SwiperClass from "swiper";

import "swiper/css";

import type {
  GalleryLabels,
  GalleryTemplate,
} from "../../templates/gallery/default-template";
import usePrefersReducedMotion from "../shared/usePrefersReducedMotion";
import Lightbox from "./Lightbox";
import type { GalleryImage } from "./types";

export type PropertyGalleryProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: GalleryTemplate;
  images: GalleryImage[];
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  /** Anchor id, so the hero's photo-count control can scroll here. */
  id?: string;
  /** Advance on its own. Always suspended under reduced motion. */
  autoplay?: boolean;
  /** Dwell per photograph, in ms. Slower than the card rows — people look. */
  autoplayDelay?: number;
  enabled?: boolean;
  labels?: Partial<GalleryLabels>;
};

const pad = (n: number) => String(n).padStart(2, "0");

/**
 * The property gallery.
 *
 * Every photograph carries a visible label, which is the point of the section:
 * a visitor should never have to work out whether they are looking at the
 * bedroom or the clubhouse.
 *
 * A one-image property gets a plain framed photograph rather than a carousel
 * with nothing to slide to.
 */
export default function PropertyGallery({
  template,
  images,
  heading,
  id = "gallery",
  autoplay = true,
  autoplayDelay = 6000,
  enabled = true,
  labels: labelOverrides,
}: PropertyGalleryProps) {
  const labels = { ...template.labels, ...labelOverrides };

  const swiperRef = useRef<SwiperClass | null>(null);
  const [active, setActive] = useState(0);
  const [category, setCategory] = useState<string | null>(null);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  const reducedMotion = usePrefersReducedMotion();

  // A photograph opened full-screen must not slide out from under the viewer.
  const lightboxOpen = lightboxIndex !== null;

  useEffect(() => {
    const swiper = swiperRef.current;
    if (!swiper || !swiper.autoplay) return;
    if (reducedMotion || lightboxOpen || !autoplay) swiper.autoplay.stop();
    else swiper.autoplay.start();
  }, [reducedMotion, lightboxOpen, autoplay]);

  const categories = useMemo(() => {
    const seen: string[] = [];
    images.forEach((image) => {
      if (image.category && !seen.includes(image.category)) seen.push(image.category);
    });
    return seen;
  }, [images]);

  const shown = useMemo(
    () => (category ? images.filter((image) => image.category === category) : images),
    [images, category]
  );

  const sync = useCallback((swiper: SwiperClass) => {
    swiperRef.current = swiper;
    // realIndex, not activeIndex: with loop enabled Swiper inserts duplicate
    // slides, and activeIndex counts those — the counter would read "10 / 8".
    setActive(swiper.realIndex);
  }, []);

  const pickCategory = useCallback((next: string | null) => {
    setCategory(next);
    setActive(0);
    swiperRef.current?.slideTo(0, 0);
  }, []);

  if (!enabled || images.length === 0) return null;

  const root = template.rootClass;
  const total = shown.length;
  /* Filters only earn their place once there is something to filter. */
  const showFilters = categories.length > 1 && images.length > 4;
  const looping = autoplay && total > 2;

  const renderLabel = (image: GalleryImage) => (
    <div className={`${root}__label`}>
      <span className={`${root}__label-rule`} aria-hidden="true" />
      {image.category ? (
        <span className={`${root}__category`}>{image.category}</span>
      ) : null}
      <span className={`${root}__name`}>{image.label}</span>
    </div>
  );

  const renderFrame = (image: GalleryImage, index: number) => (
    <div className={`${root}__frame`}>
      <img
        className={`${root}__image`}
        src={image.src}
        srcSet={image.srcSet}
        sizes={image.srcSet ? "(max-width: 760px) 88vw, 64vw" : undefined}
        alt={image.alt}
        style={image.focalPosition ? { objectPosition: image.focalPosition } : undefined}
        loading={index === 0 ? "eager" : "lazy"}
        decoding="async"
      />
      <button
        type="button"
        className={`${root}__expand`}
        onClick={() => setLightboxIndex(index)}
      >
        <LuExpand size={13} strokeWidth={1.75} aria-hidden="true" />
        {labels.expand}
      </button>
      {renderLabel(image)}
    </div>
  );

  return (
    <section className={root} id={id} aria-label={labels.region}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        {heading ? <div className={`${root}__heading`}>{heading}</div> : null}

        {showFilters ? (
          <ul className={`${root}__filters`}>
            <li>
              <button
                type="button"
                className={`${root}__filter${category === null ? ` ${root}__filter--active` : ""}`}
                aria-pressed={category === null}
                onClick={() => pickCategory(null)}
              >
                {labels.allFilter}
              </button>
            </li>
            {categories.map((name) => (
              <li key={name}>
                <button
                  type="button"
                  className={`${root}__filter${category === name ? ` ${root}__filter--active` : ""}`}
                  aria-pressed={category === name}
                  onClick={() => pickCategory(name)}
                >
                  {name}
                </button>
              </li>
            ))}
          </ul>
        ) : null}
      </div>

      {total === 1 ? (
        /* No carousel for a single photograph — nothing to slide to. */
        <div className={`${root}__inner`}>{renderFrame(shown[0], 0)}</div>
      ) : (
        <Swiper
          className={`${root}__swiper`}
          modules={[Navigation, Keyboard, A11y, Autoplay]}
          slidesPerView="auto"
          centeredSlides
          spaceBetween={22}
          keyboard={{ enabled: true }}
          loop={looping}
          autoplay={
            autoplay && !reducedMotion
              ? {
                  delay: autoplayDelay,
                  disableOnInteraction: false,
                  pauseOnMouseEnter: true,
                }
              : false
          }
          watchOverflow
          a11y={{ prevSlideMessage: labels.previous, nextSlideMessage: labels.next }}
          onSwiper={sync}
          onSlideChange={sync}
        >
          {shown.map((image, index) => (
            <SwiperSlide key={image.id}>{renderFrame(image, index)}</SwiperSlide>
          ))}
        </Swiper>
      )}

      <div className={`${root}__inner`}>
        {total > 1 ? (
          <>
            <div className={`${root}__bar`}>
              <p className={`${root}__counter`}>
                <span className={`${root}__counter-current`}>{pad(active + 1)}</span>
                <span aria-hidden="true">/ {pad(total)}</span>
                <span className="kr-sr-only">
                  {labels.counter
                    .replace("{n}", String(active + 1))
                    .replace("{total}", String(total))}
                </span>
              </p>

              <div className={`${root}__controls`}>
                <button
                  type="button"
                  className={`${root}__arrow`}
                  aria-label={labels.previous}
                  disabled={!looping && active === 0}
                  onClick={() => swiperRef.current?.slidePrev()}
                >
                  <LuArrowLeft size={17} strokeWidth={1.6} />
                </button>
                <button
                  type="button"
                  className={`${root}__arrow`}
                  aria-label={labels.next}
                  disabled={!looping && active >= total - 1}
                  onClick={() => swiperRef.current?.slideNext()}
                >
                  <LuArrowRight size={17} strokeWidth={1.6} />
                </button>
              </div>
            </div>

            {/* One growing line rather than a row of tiny dots. */}
            <div
              className={`${root}__progress`}
              style={{
                ["--kr-gal-progress" as string]: String((active + 1) / total),
              }}
              aria-hidden="true"
            >
              <span />
            </div>
          </>
        ) : null}
      </div>

      <Lightbox
        images={shown}
        index={lightboxIndex}
        labels={labels}
        onClose={() => setLightboxIndex(null)}
        onNavigate={setLightboxIndex}
      />
    </section>
  );
}
