import React from "react";
import { LuBuilding2, LuCar, LuKeyRound, LuMapPin, LuPawPrint, LuWashingMachine } from "react-icons/lu";

import template from "../../config/overview--template";
import PropertyOverview from "../../modules/overview/PropertyOverview";
import type { OverviewContent } from "../../modules/overview/PropertyOverview";
import { featuredImage } from "../../modules/property/derive";
import type { PropertyRecord } from "../../modules/property/types";
import overviewEnabled from "../../toggles/overview";
import { demoGallery } from "../gallery/property-gallery-x";
import SectionTitle from "../section-title/section-title";

export type PropertyOverviewXProps = { property: PropertyRecord };

/**
 * The property overview, configured.
 *
 * Imagery is pulled from the gallery by role rather than duplicated: the same
 * photographs tagged "overview" serve both surfaces.
 *
 * Parking, laundry and pet policy are deliberately null. The client has not
 * confirmed any of them, and the component omits a null row entirely rather
 * than printing "Pet Policy — N/A". Fill them in and the rows appear.
 */
export default function PropertyOverviewX({ property }: PropertyOverviewXProps) {
  /* This property's own photographs where it has them, falling back to the
     shared demo set while the bundled listings do not. The two images here are
     selected by ROLE from one list — which is why there is no separate large
     and small image to upload: identity is content, size is the template's. */
  const pool = property.images?.length ? property.images : demoGallery;
  const overviewImages = pool.filter((image) => image.roles?.includes("overview"));
  /* The featured photograph first, where one has been chosen. That is what
     "featured" means, and until MTC-KRP-026 nothing read it — the CMS could
     set it and the page ignored it. Falls through to exactly the previous
     behaviour when nothing is featured, which is every bundled listing. */
  const main = featuredImage({ ...property, images: pool }) || overviewImages[0] || pool[0];
  const supporting = overviewImages.find((image) => image.id !== main?.id);

  const content: OverviewContent = {
    lead:
      property.content?.lead ||
      property.summary ||
      "Comfortable homes, convenient surroundings and professional management come together here.",
    /* The property's own paragraphs where it has them. The three below are the
       fallback the twelve bundled listings still share — byte-identical to
       what the page has always shown, but no longer the only thing it can
       show. This was the single biggest gap the audit found: twelve pages of
       the same prose with no way to write about a particular building. */
    body: property.content?.paragraphs?.length
      ? property.content.paragraphs
      : [
          "This is a professionally managed community where the day-to-day is looked after: shared areas kept tidy, maintenance handled properly, and a management team you can actually reach.",
          "Homes are arranged for practical everyday living rather than for a brochure, with well-proportioned rooms, good natural light and storage where you need it.",
          "Residents have access to the shared outdoor space and on-site parking, and the surrounding neighbourhood puts everyday amenities within easy reach.",
        ],

    details: [
      { key: "type", label: "Property Type", value: property.type, icon: LuBuilding2 },
      { key: "location", label: "Location", value: property.location, icon: LuMapPin },
      { key: "management", label: "Management", value: "Kelley Road", icon: LuKeyRound },
      /* TODO(client): confirm — omitted from the page while null. */
      { key: "parking", label: "Parking", value: null, icon: LuCar },
      { key: "laundry", label: "Laundry", value: null, icon: LuWashingMachine },
      { key: "pets", label: "Pet Policy", value: null, icon: LuPawPrint },
    ],

    /* The property's OWN amenities, which the record has carried all along and
       the search filters have always used. This block used to print six
       generic labels instead, so the same visitor-facing fact had two
       unrelated sources and only one of them was per-property. An empty list
       omits the whole block, which the renderer already handles. */
    amenities: property.amenities ?? [],

    mainImage: { src: main.src, srcSet: main.srcSet, alt: main.alt },
    supportingImage: supporting
      ? { src: supporting.src, srcSet: supporting.srcSet, alt: supporting.alt }
      : undefined,

    primaryCta: { label: "View Floor Plans", href: "#floor-plans" },
    secondaryCta: { label: "Ask About This Property", href: "/contact" },
  };

  return (
    <PropertyOverview
      template={template}
      enabled={overviewEnabled}
      content={content}
      heading={
        <SectionTitle
          backgroundText="Overview"
          /* The authored heading where there is one. PropertyContent.title has
             said "defaults to the property's own name" since MTC-KRP-024; this
             is the line that makes it true. */
          title={property.content?.title?.trim() || `Welcome to ${property.title}`}
          align="left"
        />
      }
    />
  );
}
